import{_ as o,H as e,f as i,i as s}from"./chunks/framework.Cvt1eIE0.js";const k=JSON.parse('{"title":"19-백그라운드 작업","description":"","frontmatter":{},"headers":[],"relativePath":"20-background-tasks.md","filePath":"20-background-tasks.md","lastUpdated":null}'),t={name:"20-background-tasks.md"};function l(r,a,n,d,h,c){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="_19-백그라운드-작업" tabindex="-1">19-백그라운드 작업 <a class="header-anchor" href="#_19-백그라운드-작업" aria-label="Permalink to &quot;19-백그라운드 작업&quot;">​</a></h1><p>Grok Build를 사용하다 보면, 가끔 <strong>오래 걸리는 작업</strong>을 실행해야 할 때가 있습니다.</p><p>예를 들어:</p><ul><li>개발 서버를 띄우고 (<code>npm run dev</code>, <code>rails server</code>)</li><li>테스트 스위트를 전체 실행하고 (<code>npm test</code>, <code>pytest</code>)</li><li>빌드나 컴파일을 시작하고 (<code>make build</code>, <code>cargo build</code>)</li></ul><p>이런 작업들은 <strong>실행하는 데 몇 초에서 몇 분</strong>이 걸릴 수 있습니다.<br> 만약 Grok이 이런 작업을 **포그라운드(foreground)**로 실행하면, 그동안 Grok은 다른 일을 할 수 없고, 당신도 기다려야 합니다.</p><p>이런 문제를 해결하기 위해 Grok Build가 제공하는 기능이 바로 <strong>Background Tasks</strong>입니다.</p><hr><h2 id="background-tasks란-무엇인가" tabindex="-1">Background Tasks란 무엇인가? <a class="header-anchor" href="#background-tasks란-무엇인가" aria-label="Permalink to &quot;Background Tasks란 무엇인가?&quot;">​</a></h2><p><strong>Background Tasks</strong>는 Grok이 **오래 걸리는 작업을 백그라운드(뒤에서)**로 실행하게 해주는 기능입니다.</p><ul><li>작업은 즉시 시작되고, 처음 10초 정도는 출력이 실시간으로 보입니다.</li><li>그 이후에는 작업이 백그라운드로 전환되고, Grok은 다른 작업을 계속할 수 있습니다.</li><li>작업이 끝나면 Grok에게 <strong>알림</strong>이 옵니다.</li></ul><p>쉽게 말해, &quot;Grok이 한쪽에서 일을 하고 있는 동안, 당신은 다른 얘기를 할 수 있게 해주는 기능&quot;입니다.</p><hr><h2 id="background-commands-명령을-백그라운드로-실행하기" tabindex="-1">Background Commands (명령을 백그라운드로 실행하기) <a class="header-anchor" href="#background-commands-명령을-백그라운드로-실행하기" aria-label="Permalink to &quot;Background Commands (명령을 백그라운드로 실행하기)&quot;">​</a></h2><h3 id="기본-사용법" tabindex="-1">기본 사용법 <a class="header-anchor" href="#기본-사용법" aria-label="Permalink to &quot;기본 사용법&quot;">​</a></h3><p>Grok이 터미널 명령을 실행할 때, <code>is_background: true</code> 옵션을 주면 해당 명령이 백그라운드로 실행됩니다.</p><p>(내부적으로는 <code>run_terminal_cmd</code> 도구에 <code>is_background: true</code>를 전달하는 방식입니다.)</p><p><strong>예시</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>개발 서버를 백그라운드로 실행해줘.</span></span></code></pre></div><p>Grok은 <code>npm run dev</code> 같은 명령을 <code>is_background: true</code>로 실행합니다.</p><h3 id="어떻게-동작하나" tabindex="-1">어떻게 동작하나? <a class="header-anchor" href="#어떻게-동작하나" aria-label="Permalink to &quot;어떻게 동작하나?&quot;">​</a></h3><ol><li>Grok이 <code>run_terminal_cmd</code> 도구를 호출 (with <code>is_background: true</code>)</li><li>명령이 시작되고, 처음 10초 정도 출력이 보임</li><li>10초 후, 명령이 백그라운드로 전환됨</li><li>Grok은 <code>task_id</code>를 받음 (이 ID로 나중에 작업 상태를 확인할 수 있음)</li><li>작업이 끝나면 Grok에게 <strong>알림</strong>이 옴</li></ol><hr><h2 id="ctrl-g-demote-to-background-포그라운드-→-백그라운드-전환" tabindex="-1">Ctrl+G: Demote to Background (포그라운드 → 백그라운드 전환) <a class="header-anchor" href="#ctrl-g-demote-to-background-포그라운드-→-백그라운드-전환" aria-label="Permalink to &quot;Ctrl+G: Demote to Background (포그라운드 → 백그라운드 전환)&quot;">​</a></h2><p>TUI(터미널 UI)에서 작업이 실행되고 있을 때, <strong>Ctrl+G</strong>를 누르면 현재 실행 중인 작업을 <strong>강제로 백그라운드로 전환</strong>할 수 있습니다.</p><h3 id="언제-ctrl-g를-사용하면-좋을까" tabindex="-1">언제 Ctrl+G를 사용하면 좋을까? <a class="header-anchor" href="#언제-ctrl-g를-사용하면-좋을까" aria-label="Permalink to &quot;언제 Ctrl+G를 사용하면 좋을까?&quot;">​</a></h3><ul><li>명령이 예상보다 오래 걸릴 때</li><li>Grok에게 다른 질문을 하고 싶을 때</li><li>&quot;이 작업은 오래 걸리겠구나&quot;라고 미리 알게 되었을 때</li></ul><p><strong>예시 상황</strong>:</p><ul><li><code>npm install</code>을 실행했는데, 생각보다 오래 걸림</li><li><code>Ctrl+G</code>를 눌러서 백그라운드로 전환</li><li>Grok에게 &quot;이 프로젝트의 구조를 분석해줘&quot;라고 질문</li></ul><p>Grok은 백그라운드 작업을 계속 실행하면서, 당신의 질문에 답변할 수 있습니다.</p><p>작업이 끝나면 Grok에게 <strong>알림</strong>이 옵니다.</p><hr><h2 id="background-task-관리" tabindex="-1">Background Task 관리 <a class="header-anchor" href="#background-task-관리" aria-label="Permalink to &quot;Background Task 관리&quot;">​</a></h2><h3 id="작업-상태-확인-get-task-output" tabindex="-1">작업 상태 확인 (<code>get_task_output</code>) <a class="header-anchor" href="#작업-상태-확인-get-task-output" aria-label="Permalink to &quot;작업 상태 확인 (`get_task_output`)&quot;">​</a></h3><p>백그라운드 작업의 현재 상태와 출력을 확인하려면 <code>get_task_output</code> 도구를 사용합니다.</p><ul><li><code>get_task_output(task_id)</code>: 현재 상태와 출력 확인 (non-blocking)</li><li><code>get_task_output(task_id, block=true)</code>: 작업이 끝날 때까지 기다림</li><li><code>get_task_output(task_id, block=true, timeout_ms=30000)</code>: 최대 30초까지 기다림</li></ul><p><strong>실전 팁</strong>:</p><ul><li>&quot;백그라운드 작업 상태가 어때?&quot;라고 물으면 Grok이 <code>get_task_output</code>을 호출합니다.</li><li><code>block=true</code>를 사용하면 작업이 끝날 때까지 기다렸다가 결과를 알려줍니다.</li></ul><h3 id="작업-종료-kill-task" tabindex="-1">작업 종료 (<code>kill_task</code>) <a class="header-anchor" href="#작업-종료-kill-task" aria-label="Permalink to &quot;작업 종료 (`kill_task`)&quot;">​</a></h3><p>백그라운드 작업을 강제로 종료하려면 <code>kill_task</code> 도구를 사용합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kill_task(task_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li>shell 프로세스의 경우: <code>SIGTERM</code> → <code>SIGKILL</code> 순으로 종료 시도</li><li>Subagent의 경우: <code>Cancel+Shutdown</code> 신호 전송</li></ul><p><strong>실전 팁</strong>:</p><ul><li>&quot;백그라운드 작업 중단해줘&quot;라고 하면 Grok이 <code>kill_task</code>를 호출합니다.</li><li>작업이 너무 오래 걸리거나, 더 이상 필요 없을 때 사용하세요.</li></ul><hr><h2 id="common-use-cases-자주-쓰이는-상황" tabindex="-1">Common Use Cases (자주 쓰이는 상황) <a class="header-anchor" href="#common-use-cases-자주-쓰이는-상황" aria-label="Permalink to &quot;Common Use Cases (자주 쓰이는 상황)&quot;">​</a></h2><h3 id="_1-개발-서버-실행" tabindex="-1">1. 개발 서버 실행 <a class="header-anchor" href="#_1-개발-서버-실행" aria-label="Permalink to &quot;1. 개발 서버 실행&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>개발 서버를 백그라운드로 실행해줘.</span></span></code></pre></div><ul><li><code>npm run dev</code>, <code>rails server</code>, <code>python manage.py runserver</code> 등</li><li>서버가 실행되는 동안 다른 작업(코드 수정, 테스트 등)을 계속할 수 있음</li></ul><h3 id="_2-테스트-스위트-실행" tabindex="-1">2. 테스트 스위트 실행 <a class="header-anchor" href="#_2-테스트-스위트-실행" aria-label="Permalink to &quot;2. 테스트 스위트 실행&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>테스트를 백그라운드로 실행해줘.</span></span></code></pre></div><ul><li><code>npm test</code>, <code>pytest</code>, <code>cargo test</code> 등</li><li>테스트가 실행되는 동안 다른 파일을 수정하거나, Grok에게 다른 질문을 할 수 있음</li></ul><h3 id="_3-빌드-컴파일" tabindex="-1">3. 빌드/컴파일 <a class="header-anchor" href="#_3-빌드-컴파일" aria-label="Permalink to &quot;3. 빌드/컴파일&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>빌드를 백그라운드로 실행해줘.</span></span></code></pre></div><ul><li><code>make build</code>, <code>cargo build</code>, <code>npm run build</code> 등</li><li>빌드가 끝나면 Grok이 알려줌</li></ul><h3 id="_4-긴-컴파일-작업" tabindex="-1">4. 긴 컴파일 작업 <a class="header-anchor" href="#_4-긴-컴파일-작업" aria-label="Permalink to &quot;4. 긴 컴파일 작업&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>이 C++ 프로젝트를 컴파일해줘.</span></span></code></pre></div><ul><li>컴파일이 오래 걸리는 프로젝트에서 특히 유용</li><li>Ctrl+G로 백그라운드 전환 → 다른 작업 계속</li></ul><hr><p>지금까지 다음 내용을 다루었습니다:</p><ul><li>Background Tasks의 개념</li><li>Background Commands (is_background: true)</li><li>Ctrl+G: Demote to Background</li><li>Background Task 관리 (get_task_output, kill_task)</li><li>Common Use Cases</li></ul><hr><h2 id="loop-명령어-반복-작업-스케줄링" tabindex="-1">/loop 명령어 (반복 작업 스케줄링) <a class="header-anchor" href="#loop-명령어-반복-작업-스케줄링" aria-label="Permalink to &quot;/loop 명령어 (반복 작업 스케줄링)&quot;">​</a></h2><p><code>/loop</code> 명령어는 <strong>특정 작업을 주기적으로 반복</strong>해서 실행하게 해주는 명령어입니다.</p><h3 id="기본-사용법-1" tabindex="-1">기본 사용법 <a class="header-anchor" href="#기본-사용법-1" aria-label="Permalink to &quot;기본 사용법&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;이 프로젝트의 테스트를 실행해줘&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> every</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minutes</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;데이터베이스 백업 상태를 확인해줘&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> every</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hour</span></span></code></pre></div><ul><li>Grok이 지정된 간격마다 자동으로 해당 작업을 실행합니다.</li><li>작업이 끝나면 결과가 대화에 추가됩니다.</li></ul><h3 id="loop의-특징" tabindex="-1">/loop의 특징 <a class="header-anchor" href="#loop의-특징" aria-label="Permalink to &quot;/loop의 특징&quot;">​</a></h3><ul><li><strong>지속적 실행</strong>: Grok 세션이 열려 있는 동안 계속 반복됩니다.</li><li><strong>수동 종료 필요</strong>: <code>/loop</code>를 중지하려면 별도로 명령해야 합니다.</li><li><strong>알림 형태</strong>: 작업 결과가 대화에 메시지로 추가됩니다.</li></ul><p><strong>실전 팁</strong>:</p><ul><li>&quot;30분마다 테스트 실행&quot; 같은 반복적인 모니터링 작업에 유용합니다.</li><li>하지만 너무 자주 실행하면 Grok의 컨텍스트가 불필요하게 채워질 수 있으니 주의하세요.</li></ul><hr><h2 id="monitor-도구-장시간-실행되는-프로세스-실시간-모니터링" tabindex="-1">monitor 도구 (장시간 실행되는 프로세스 실시간 모니터링) <a class="header-anchor" href="#monitor-도구-장시간-실행되는-프로세스-실시간-모니터링" aria-label="Permalink to &quot;monitor 도구 (장시간 실행되는 프로세스 실시간 모니터링)&quot;">​</a></h2><p><code>monitor</code> 도구는 <strong>장시간 실행되는 프로세스나 백그라운드 작업을 실시간으로 관찰</strong>할 수 있게 해주는 도구입니다.</p><h3 id="monitor-도구-사용법" tabindex="-1">monitor 도구 사용법 <a class="header-anchor" href="#monitor-도구-사용법" aria-label="Permalink to &quot;monitor 도구 사용법&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monitor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;npm run dev&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --persistent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monitor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tail -f /var/log/app.log&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --description</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Application log monitor&quot;</span></span></code></pre></div><ul><li><code>persistent: true</code>로 설정하면, Grok 세션이 끝나도 모니터링이 계속됩니다.</li><li><code>description</code>을 지정하면, 모니터링의 목적을 명확히 할 수 있습니다.</li></ul><h3 id="monitor-도구의-특징" tabindex="-1">monitor 도구의 특징 <a class="header-anchor" href="#monitor-도구의-특징" aria-label="Permalink to &quot;monitor 도구의 특징&quot;">​</a></h3><ul><li><strong>실시간 스트리밍</strong>: 프로세스의 출력이 실시간으로 Grok에게 전달됩니다.</li><li><strong>지속성</strong>: Grok 세션이 종료되어도 모니터링이 계속될 수 있습니다.</li><li><strong>설명 추가 가능</strong>: <code>description</code>으로 모니터링의 목적을 기록할 수 있습니다.</li></ul><p><strong>실전 팁</strong>:</p><ul><li>개발 서버(<code>npm run dev</code>, <code>rails server</code>)를 띄워놓고, 그 출력을 실시간으로 관찰할 때 유용합니다.</li><li>로그 파일을 <code>tail -f</code>로 모니터링하면서, 에러가 발생하면 Grok이 자동으로 알려줄 수 있습니다.</li></ul><hr><h2 id="scheduler-시스템-cron-like-반복-작업" tabindex="-1">Scheduler 시스템 (cron-like 반복 작업) <a class="header-anchor" href="#scheduler-시스템-cron-like-반복-작업" aria-label="Permalink to &quot;Scheduler 시스템 (cron-like 반복 작업)&quot;">​</a></h2><p>Grok Build는 <strong>Scheduler</strong> 시스템을 통해, <strong>cron</strong>처럼 특정 시간에 반복적으로 작업을 실행할 수 있습니다.</p><h3 id="scheduler-사용법" tabindex="-1">Scheduler 사용법 <a class="header-anchor" href="#scheduler-사용법" aria-label="Permalink to &quot;Scheduler 사용법&quot;">​</a></h3><p>Scheduler는 <code>/loop</code>와 유사하지만, <strong>더 정교한 스케줄링</strong>이 가능합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;매일 오전 9시에 이 프로젝트의 빌드 상태를 확인해줘&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> every</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> day</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9am</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;매주 월요일에 코드 품질 리포트를 작성해줘&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> every</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monday</span></span></code></pre></div><h3 id="scheduler의-특징" tabindex="-1">Scheduler의 특징 <a class="header-anchor" href="#scheduler의-특징" aria-label="Permalink to &quot;Scheduler의 특징&quot;">​</a></h3><ul><li><strong>시간 기반 스케줄링</strong>: &quot;매일&quot;, &quot;매주&quot;, &quot;특정 시간&quot; 등으로 지정 가능</li><li><strong>지속성</strong>: Grok 세션이 종료되어도 스케줄러는 계속 동작할 수 있습니다.</li><li><strong>알림 형태</strong>: 작업 결과가 대화에 메시지로 추가됩니다.</li></ul><p><strong>실전 팁</strong>:</p><ul><li>&quot;매일 아침 9시에 빌드 상태 확인&quot; 같은 정기적인 모니터링 작업에 적합합니다.</li><li><code>/loop</code>보다 더 명확한 시간 지정이 가능합니다.</li></ul><hr><h2 id="background-tasks와-subagent의-연동" tabindex="-1">Background Tasks와 Subagent의 연동 <a class="header-anchor" href="#background-tasks와-subagent의-연동" aria-label="Permalink to &quot;Background Tasks와 Subagent의 연동&quot;">​</a></h2><p>Background Tasks와 Subagent를 함께 사용하면, 더 강력한 자동화가 가능합니다.</p><h3 id="예시-subagent-background-task" tabindex="-1">예시: Subagent + Background Task <a class="header-anchor" href="#예시-subagent-background-task" aria-label="Permalink to &quot;예시: Subagent + Background Task&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>이 프로젝트의 테스트를 Subagent로 백그라운드에서 실행해줘.</span></span></code></pre></div><p>Grok이 Subagent를 생성하고, 그 안에서 <code>is_background: true</code>로 테스트를 실행할 수 있습니다.</p><h3 id="예시-monitor-subagent" tabindex="-1">예시: monitor + Subagent <a class="header-anchor" href="#예시-monitor-subagent" aria-label="Permalink to &quot;예시: monitor + Subagent&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>이 개발 서버를 Subagent로 모니터링하면서, 에러가 발생하면 알려줘.</span></span></code></pre></div><p>Grok이 Subagent를 생성하고, <code>monitor</code> 도구로 서버 출력을 실시간으로 관찰하면서, 에러가 발생하면 메인 세션에 알림을 보낼 수 있습니다.</p><h3 id="연동의-장점" tabindex="-1">연동의 장점 <a class="header-anchor" href="#연동의-장점" aria-label="Permalink to &quot;연동의 장점&quot;">​</a></h3><ul><li><strong>병렬 처리</strong>: 메인 세션은 다른 작업을 하면서, Subagent가 백그라운드 작업을 수행</li><li><strong>실시간 모니터링</strong>: <code>monitor</code> 도구로 Subagent의 작업을 실시간으로 관찰</li><li><strong>알림</strong>: 작업 완료나 에러 발생 시 메인 세션에 자동으로 알림</li></ul><hr><p>지금까지 <code>/loop</code>, <code>monitor</code>, Scheduler 시스템, 그리고 Background Tasks와 Subagent의 연동을 다루었습니다.</p><hr><h2 id="scheduler-상세-설정" tabindex="-1">Scheduler 상세 설정 <a class="header-anchor" href="#scheduler-상세-설정" aria-label="Permalink to &quot;Scheduler 상세 설정&quot;">​</a></h2><p>Scheduler는 <code>/loop</code>보다 더 정교한 스케줄링을 지원합니다.</p><h3 id="cron-like-문법" tabindex="-1">cron-like 문법 <a class="header-anchor" href="#cron-like-문법" aria-label="Permalink to &quot;cron-like 문법&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;이 프로젝트의 빌드 상태를 확인해줘&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> every</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> day</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9am</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;코드 품질 리포트를 작성해줘&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> every</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monday</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10am</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;데이터베이스 백업 상태를 체크해줘&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> every</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hour</span></span></code></pre></div><ul><li><code>every day at 9am</code>: 매일 오전 9시</li><li><code>every monday</code>: 매주 월요일</li><li><code>every hour</code>: 매시간</li></ul><h3 id="durable-옵션" tabindex="-1">durable 옵션 <a class="header-anchor" href="#durable-옵션" aria-label="Permalink to &quot;durable 옵션&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> durable:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><ul><li><code>durable: true</code>로 설정하면, Grok 세션이 종료되어도 스케줄러가 계속 동작합니다.</li><li>Grok을 다시 시작해도 스케줄이 유지됩니다.</li></ul><h3 id="persistent-옵션" tabindex="-1">persistent 옵션 <a class="header-anchor" href="#persistent-옵션" aria-label="Permalink to &quot;persistent 옵션&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monitor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;npm run dev&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --persistent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><ul><li><code>persistent: true</code>로 설정하면, Grok 세션이 끝나도 모니터링이 계속됩니다.</li><li>로그 파일을 실시간으로 관찰하는 경우에 유용합니다.</li></ul><h3 id="scheduler-관리" tabindex="-1">Scheduler 관리 <a class="header-anchor" href="#scheduler-관리" aria-label="Permalink to &quot;Scheduler 관리&quot;">​</a></h3><ul><li><code>/loop list</code>: 현재 실행 중인 스케줄러 목록</li><li><code>/loop stop &lt;id&gt;</code>: 특정 스케줄러 중지</li><li><code>/loop clear</code>: 모든 스케줄러 중지</li></ul><hr><h2 id="background-tasks-관련-best-practices" tabindex="-1">Background Tasks 관련 Best Practices <a class="header-anchor" href="#background-tasks-관련-best-practices" aria-label="Permalink to &quot;Background Tasks 관련 Best Practices&quot;">​</a></h2><h3 id="_1-background-task는-긴-작업-에만-사용하라" tabindex="-1">1. Background Task는 &quot;긴 작업&quot;에만 사용하라 <a class="header-anchor" href="#_1-background-task는-긴-작업-에만-사용하라" aria-label="Permalink to &quot;1. Background Task는 &quot;긴 작업&quot;에만 사용하라&quot;">​</a></h3><ul><li>10초 이내에 끝나는 작업은 포그라운드로 실행하는 것이 오히려 좋습니다.</li><li>Background Task는 &quot;기다리는 동안 다른 일을 하고 싶을 때&quot; 유용합니다.</li></ul><h3 id="_2-ctrl-g를-적극-활용하라" tabindex="-1">2. Ctrl+G를 적극 활용하라 <a class="header-anchor" href="#_2-ctrl-g를-적극-활용하라" aria-label="Permalink to &quot;2. Ctrl+G를 적극 활용하라&quot;">​</a></h3><ul><li>작업이 시작된 후 &quot;이게 오래 걸리겠구나&quot; 싶으면, 바로 <code>Ctrl+G</code>로 백그라운드 전환하세요.</li><li>미리 <code>is_background: true</code>를 지정하지 않아도, 실행 중에 전환할 수 있습니다.</li></ul><h3 id="_3-monitor-도구는-지속적인-관찰-에-사용하라" tabindex="-1">3. <code>monitor</code> 도구는 &quot;지속적인 관찰&quot;에 사용하라 <a class="header-anchor" href="#_3-monitor-도구는-지속적인-관찰-에-사용하라" aria-label="Permalink to &quot;3. `monitor` 도구는 &quot;지속적인 관찰&quot;에 사용하라&quot;">​</a></h3><ul><li>개발 서버, 로그 파일, 메시지 큐 등을 실시간으로 관찰할 때 유용합니다.</li><li><code>persistent: true</code>를 사용하면 Grok 세션이 끝나도 모니터링이 계속됩니다.</li></ul><h3 id="_4-scheduler는-정기적인-작업-에-사용하라" tabindex="-1">4. Scheduler는 &quot;정기적인 작업&quot;에 사용하라 <a class="header-anchor" href="#_4-scheduler는-정기적인-작업-에-사용하라" aria-label="Permalink to &quot;4. Scheduler는 &quot;정기적인 작업&quot;에 사용하라&quot;">​</a></h3><ul><li>매일 아침 빌드 상태 확인</li><li>매주 월요일 코드 품질 리포트 작성</li><li>매시간 데이터베이스 상태 체크</li></ul><h3 id="_5-subagent와의-연동은-복잡한-자동화-에-사용하라" tabindex="-1">5. Subagent와의 연동은 &quot;복잡한 자동화&quot;에 사용하라 <a class="header-anchor" href="#_5-subagent와의-연동은-복잡한-자동화-에-사용하라" aria-label="Permalink to &quot;5. Subagent와의 연동은 &quot;복잡한 자동화&quot;에 사용하라&quot;">​</a></h3><ul><li>Subagent가 백그라운드 작업을 수행하면서, 메인 세션은 다른 일을 할 수 있습니다.</li><li><code>monitor</code>와 Subagent를 함께 사용하면, Subagent의 작업을 실시간으로 관찰할 수 있습니다.</li></ul><hr><h2 id="자주-발생하는-문제와-해결-방법-troubleshooting" tabindex="-1">자주 발생하는 문제와 해결 방법 (Troubleshooting) <a class="header-anchor" href="#자주-발생하는-문제와-해결-방법-troubleshooting" aria-label="Permalink to &quot;자주 발생하는 문제와 해결 방법 (Troubleshooting)&quot;">​</a></h2><h3 id="_1-background-task가-시작되지-않는다" tabindex="-1">1. Background Task가 시작되지 않는다 <a class="header-anchor" href="#_1-background-task가-시작되지-않는다" aria-label="Permalink to &quot;1. Background Task가 시작되지 않는다&quot;">​</a></h3><p><strong>증상</strong>: &quot;백그라운드로 실행해줘&quot;라고 했는데, 작업이 포그라운드로 실행됨</p><p><strong>해결</strong>:</p><ul><li>Grok이 <code>is_background: true</code>를 제대로 인식했는지 확인</li><li>&quot;백그라운드로 실행해줘&quot;라고 명확히 말하세요.</li></ul><h3 id="_2-background-task의-결과를-받지-못한다" tabindex="-1">2. Background Task의 결과를 받지 못한다 <a class="header-anchor" href="#_2-background-task의-결과를-받지-못한다" aria-label="Permalink to &quot;2. Background Task의 결과를 받지 못한다&quot;">​</a></h3><p><strong>증상</strong>: 작업이 끝났는데 알림이 오지 않음</p><p><strong>해결</strong>:</p><ul><li><code>get_task_output(task_id, block=true)</code>를 사용해서 작업이 끝날 때까지 기다려보세요.</li><li>작업이 너무 오래 걸리면 <code>timeout_ms</code>를 늘려보세요.</li></ul><h3 id="_3-loop가-너무-자주-실행된다" tabindex="-1">3. <code>/loop</code>가 너무 자주 실행된다 <a class="header-anchor" href="#_3-loop가-너무-자주-실행된다" aria-label="Permalink to &quot;3. `/loop`가 너무 자주 실행된다&quot;">​</a></h3><p><strong>증상</strong>: <code>/loop</code>로 설정한 작업이 너무 자주 실행되어 Grok이 바쁨</p><p><strong>해결</strong>:</p><ul><li>스케줄 간격을 늘리세요 (<code>every hour</code> → <code>every 3 hours</code>)</li><li>작업 자체를 가볍게 만드세요.</li></ul><h3 id="_4-monitor가-너무-많은-출력을-보여준다" tabindex="-1">4. <code>monitor</code>가 너무 많은 출력을 보여준다 <a class="header-anchor" href="#_4-monitor가-너무-많은-출력을-보여준다" aria-label="Permalink to &quot;4. `monitor`가 너무 많은 출력을 보여준다&quot;">​</a></h3><p><strong>증상</strong>: <code>monitor</code>로 로그를 보고 있는데, 너무 많은 로그가 쌓여서 대화가 지저분함</p><p><strong>해결</strong>:</p><ul><li><code>monitor</code>에 <code>description</code>을 지정해서, 어떤 모니터링인지 명확히 하세요.</li><li>필요할 때만 <code>monitor</code>를 사용하고, 끝나면 중지하세요.</li></ul><h3 id="_5-scheduler가-grok-세션이-끝난-후에도-동작하지-않는다" tabindex="-1">5. Scheduler가 Grok 세션이 끝난 후에도 동작하지 않는다 <a class="header-anchor" href="#_5-scheduler가-grok-세션이-끝난-후에도-동작하지-않는다" aria-label="Permalink to &quot;5. Scheduler가 Grok 세션이 끝난 후에도 동작하지 않는다&quot;">​</a></h3><p><strong>증상</strong>: Grok을 종료했는데, <code>/loop</code>나 <code>monitor</code>가 중지됨</p><p><strong>해결</strong>:</p><ul><li><code>durable: true</code> 또는 <code>persistent: true</code> 옵션을 사용하세요.</li><li>Grok을 다시 시작해도 스케줄이 유지되게 하려면, 이 옵션을 꼭 사용해야 합니다.</li></ul><hr><h2 id="전체-가이드-마무리" tabindex="-1">전체 가이드 마무리 <a class="header-anchor" href="#전체-가이드-마무리" aria-label="Permalink to &quot;전체 가이드 마무리&quot;">​</a></h2><p><code>19-백그라운드-작업.md</code>를 모두 읽었다면, 이제 Grok Build의 <strong>백그라운드 작업과 모니터링</strong> 기능을 이해한 것입니다.</p><h3 id="핵심-요약" tabindex="-1">핵심 요약 <a class="header-anchor" href="#핵심-요약" aria-label="Permalink to &quot;핵심 요약&quot;">​</a></h3><ul><li><strong>Background Commands</strong>: <code>is_background: true</code>로 긴 작업을 백그라운드로 실행</li><li><strong>Ctrl+G</strong>: 실행 중인 작업을 즉시 백그라운드로 전환</li><li><strong><code>/loop</code></strong>: 반복적인 작업을 주기적으로 실행</li><li><strong><code>monitor</code></strong>: 장시간 실행되는 프로세스를 실시간으로 관찰</li><li><strong>Scheduler</strong>: cron-like로 정기적인 작업을 자동화</li><li><strong>Subagent + Background Tasks</strong>: 병렬 처리와 실시간 모니터링의 강력한 조합</li></ul><h3 id="background-tasks-추천-사용처" tabindex="-1">Background Tasks 추천 사용처 <a class="header-anchor" href="#background-tasks-추천-사용처" aria-label="Permalink to &quot;Background Tasks 추천 사용처&quot;">​</a></h3><ul><li>개발 서버 실행</li><li>테스트 스위트 실행</li><li>빌드/컴파일</li><li>로그 모니터링</li><li>정기적인 상태 체크</li><li>병렬 작업 처리</li></ul><hr><p><strong>19-백그라운드-작업.md 끝</strong></p><p>여기까지 Grok Build의 Background Tasks와 모니터링 기능을 실전 관점에서 정리했습니다.</p><p>이 기능들을 잘 활용하면, Grok이 &quot;한 가지 일만 하는 AI&quot;가 아니라 <strong>여러 일을 동시에 처리할 수 있는 AI</strong>가 됩니다.</p><p>특히 CI/CD, 자동화, 모니터링이 중요한 환경에서는 이 기능들이 매우 강력한 도구가 될 것입니다.</p><p>이 문서에서 다루지 않은 더 고급 활용법이나 특정 환경에서의 문제 해결이 필요하시면 언제든 말씀해주세요.</p><hr><p><em>이 가이드는 실제 자동화 환경에서 Background Tasks를 활용했던 경험을 바탕으로 작성되었습니다.</em></p><ul><li><code>/loop</code> 명령어 (반복 작업 스케줄링)</li><li><code>monitor</code> 도구 (장시간 실행되는 프로세스 실시간 모니터링)</li><li>Scheduler 시스템 (cron-like 반복 작업)</li><li>Background Tasks와 Subagent의 연동</li></ul><hr><hr><h2 id="배경-지식-이-기능이-왜-이렇게-동작하는가" tabindex="-1">배경 지식: 이 기능이 왜 이렇게 동작하는가 <a class="header-anchor" href="#배경-지식-이-기능이-왜-이렇게-동작하는가" aria-label="Permalink to &quot;배경 지식: 이 기능이 왜 이렇게 동작하는가&quot;">​</a></h2><blockquote><p><strong>참고</strong>: 이 섹션은 Grok 공식 문서에 명시된 설계 의도를 그대로 설명한 것이 아닙니다.<br> 실제 동작 방식과 관찰, 그리고 논리적 해석을 바탕으로 작성한 <strong>참고용 설명</strong>입니다.<br> xAI에서 공식적으로 발표한 설계 철학이 아니라는 점을 참고해 주세요.</p></blockquote><p>Background Tasks 기능이 현재와 같은 형태로 제공되는 배경과 특징을 정리했습니다.</p><h3 id="_1-왜-10초-후에-자동으로-백그라운드로-보내는가" tabindex="-1">1. 왜 10초 후에 자동으로 백그라운드로 보내는가? <a class="header-anchor" href="#_1-왜-10초-후에-자동으로-백그라운드로-보내는가" aria-label="Permalink to &quot;1. 왜 10초 후에 자동으로 백그라운드로 보내는가?&quot;">​</a></h3><p>Grok이 오래 걸리는 명령을 실행할 때, 처음 10초 동안은 출력이 실시간으로 보이도록 했습니다.</p><p>이유는 두 가지입니다:</p><ul><li>사용자가 &quot;지금 이 작업이 잘 되고 있는지&quot;를 바로 확인할 수 있게 하기 위해</li><li>10초가 지나면 대부분의 긴 작업(빌드, 테스트, 서버 실행)의 초기 로그가 충분히 나오기 때문</li></ul><p>이후에는 Grok이 다른 일을 할 수 있도록 자동으로 백그라운드 전환을 하는 방식으로 동작합니다.</p><h3 id="_2-왜-ctrl-g로-수동-demote가-가능한가" tabindex="-1">2. 왜 Ctrl+G로 수동 demote가 가능한가? <a class="header-anchor" href="#_2-왜-ctrl-g로-수동-demote가-가능한가" aria-label="Permalink to &quot;2. 왜 Ctrl+G로 수동 demote가 가능한가?&quot;">​</a></h3><p>때로는 &quot;이 작업은 백그라운드로 보내고, 지금은 다른 얘기를 하고 싶다&quot;고 판단하는 순간이 있습니다.</p><p>이때 <strong>Ctrl+G</strong>를 누르면 현재 실행 중인 포그라운드 작업을 강제로 백그라운드로 보낼 수 있습니다.</p><p>이 기능은 사용자가 직접 작업의 실행 방식을 제어할 수 있게 해줍니다.</p><h3 id="_3-왜-loop-scheduler-도-함께-제공하나" tabindex="-1">3. 왜 /loop (Scheduler)도 함께 제공하나? <a class="header-anchor" href="#_3-왜-loop-scheduler-도-함께-제공하나" aria-label="Permalink to &quot;3. 왜 /loop (Scheduler)도 함께 제공하나?&quot;">​</a></h3><p>Background Tasks는 &quot;한 번 실행하고 잊기&quot; 위한 기능입니다.<br> 반면 <code>/loop</code>는 <strong>주기적으로 반복</strong> 실행하기 위한 기능입니다 (cron-like).</p><p>이 둘을 함께 제공함으로써:</p><ul><li>일회성 긴 작업 → Background Tasks</li><li>정기적인 모니터링/빌드 → /loop + Scheduler</li></ul><p>라는 명확한 역할 분리를 할 수 있게 했습니다.</p><hr><h2 id="디버깅-체크리스트" tabindex="-1">디버깅 체크리스트 <a class="header-anchor" href="#디버깅-체크리스트" aria-label="Permalink to &quot;디버깅 체크리스트&quot;">​</a></h2><p>Background Tasks 관련 문제가 발생할 때, 아래 순서대로 확인해보세요.</p><h3 id="백그라운드-작업이-끝났는데도-알림이-안-올-때" tabindex="-1">백그라운드 작업이 끝났는데도 알림이 안 올 때 <a class="header-anchor" href="#백그라운드-작업이-끝났는데도-알림이-안-올-때" aria-label="Permalink to &quot;백그라운드 작업이 끝났는데도 알림이 안 올 때&quot;">​</a></h3><ol><li><strong>monitor 명령어로 상태 확인</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monitor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">task_i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div></li><li>작업이 실제로 종료되었는지, 아니면 아직 실행 중인지 확인하세요.</li></ol><h3 id="ctrl-g가-안-먹힐-때" tabindex="-1">Ctrl+G가 안 먹힐 때 <a class="header-anchor" href="#ctrl-g가-안-먹힐-때" aria-label="Permalink to &quot;Ctrl+G가 안 먹힐 때&quot;">​</a></h3><ul><li>TUI에서 실제로 포그라운드 작업이 실행 중일 때만 동작합니다.</li><li>이미 백그라운드 상태이거나, Grok이 입력을 기다리고 있는 상태에서는 무시됩니다.</li><li>Vim mode를 사용 중이라면 <code>Ctrl+G</code>가 다른 의미일 수 있으니 Simple mode로 전환해보세요.</li></ul><h3 id="background-task가-너무-많이-쌓일-때" tabindex="-1">background task가 너무 많이 쌓일 때 <a class="header-anchor" href="#background-task가-너무-많이-쌓일-때" aria-label="Permalink to &quot;background task가 너무 많이 쌓일 때&quot;">​</a></h3><ul><li><code>grok background list</code> 또는 TUI에서 <code>Ctrl+G</code> 후 상태를 확인할 수 있습니다.</li><li>불필요한 background task는 <code>grok background kill &lt;id&gt;</code>로 정리하는 습관을 들이는 것이 좋습니다.</li></ul><h3 id="개발-서버를-background로-띄웠는데-로그를-보고-싶을-때" tabindex="-1">개발 서버를 background로 띄웠는데 로그를 보고 싶을 때 <a class="header-anchor" href="#개발-서버를-background로-띄웠는데-로그를-보고-싶을-때" aria-label="Permalink to &quot;개발 서버를 background로 띄웠는데 로그를 보고 싶을 때&quot;">​</a></h3><ul><li><code>grok monitor &lt;task_id&gt;</code>를 사용하면 실시간으로 로그를 볼 수 있습니다.</li><li>또는 <code>grok logs &lt;task_id&gt;</code> 같은 명령으로 과거 로그를 확인할 수 있습니다.</li></ul><h3 id="loop-스케줄러와-background-tasks를-혼동할-때" tabindex="-1">/loop 스케줄러와 Background Tasks를 혼동할 때 <a class="header-anchor" href="#loop-스케줄러와-background-tasks를-혼동할-때" aria-label="Permalink to &quot;/loop 스케줄러와 Background Tasks를 혼동할 때&quot;">​</a></h3><ul><li>한 번만 실행하는 긴 작업 → Background Tasks (<code>is_background: true</code>)</li><li>주기적으로 반복 실행 → <code>/loop</code> 또는 Scheduler</li></ul><p>이 구분을 명확히 하면 훨씬 편하게 사용할 수 있습니다.</p><hr><p>이 두 섹션은 Background Tasks와 Scheduler를 사용할 때 발생하는 문제를 스스로 해결할 수 있도록 돕기 위해 추가되었습니다.</p>',202)])])}const p=o(t,[["render",l]]);export{k as __pageData,p as default};
